SELECT COUNT(*) N, COUNT(DISTINCT COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci) LIVROS, COUNT(DISTINCT L.VIDEO_ID) VIDEOS FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})